  "CAP_Theorem": {
    "description": "The CAP theorem states that in a distributed system, it is impossible to simultaneously guarantee Consistency, Availability, and Partition tolerance. A system can only have at most two of these three properties.",
    "components": {
      "Consistency": "Every read receives the most recent write or an error.",
      "Availability": "Every request receives a (non-error) response, without guarantee that it contains the most recent write.",
      "Partition_Tolerance": "The system continues to operate despite arbitrary partitioning due to network failures."
    },
    "examples": [
      {
        "example": "Cassandra",
        "properties": ["Availability", "Partition_Tolerance"],
        "explanation": "Cassandra prioritizes high availability and partition tolerance. It allows for some inconsistency to ensure that all nodes can respond to requests even during network partitions."
      },
      {
        "example": "MongoDB",
        "properties": ["Consistency", "Partition_Tolerance"],
        "explanation": "MongoDB ensures consistency by using a primary node for writes and replicating data. However, during a network partition, it may sacrifice availability by not allowing writes to secondary nodes."
      },
      {
        "example": "Riak",
        "properties": ["Availability", "Partition_Tolerance"],
        "explanation": "Riak is designed for high availability and partition tolerance. It allows data to be written to multiple nodes and reconciles conflicts later, which can lead to temporary inconsistencies."
