"function mergeTwoLists(l1, l2) {
    // Create a dummy node to act as the starting point of the merged list
    let dummy = new ListNode(0);
    let current = dummy;

    // Traverse both lists until one is empty
    while (l1 && l2) {
        if (l1.val < l2.val) {
            current.next = l1;
            l1 = l1.next;
        } else {
            current.next = l2;
            l2 = l2.next;
        }
        current = current.next;
    }

    // Attach the remaining elements from whichever list is not empty
    current.next = l1 || l2;

    // The merged list starts at dummy.next
    return dummy.next;
}

// Definition for singly-linked list node
class ListNode {
    constructor(val, next = null) {
        this.val = val;
        this.next = next;
    }
