"package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
)

// Function to read a JSON file and print top-level keys
func printTopLevelKeys(filename string) error {
	// Read the file
	data, err := ioutil.ReadFile(filename)
	if err != nil {
		return err
	}

	// Parse the JSON
	var obj map[string]interface{}
	if err := json.Unmarshal(data, &obj); err != nil {
		return err
	}

	// Print top-level keys
	for key := range obj {
		fmt.Println(key)
	}

	return nil
}

func main() {
	// Check if filename is provided
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run main.go <filename.json>")
		return
	}

	// Get the filename from command line argument
	filename := os.Args[1]

	// Call the function and handle errors
	if err := printTopLevelKeys(filename); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}"
